return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n % 10 != 1 || n % 100 == 11;','language'=>'is_IS','project-id-version'=>'Babilim 1.2.1','pot-creation-date'=>'2026-11-09T07:54:23+00:00','po-revision-date'=>'2026-11-09T07:54:23+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'Sent þegar þú ýtir á Virkja Babilim, og aftur ef vefsvæðið þarf að skrá sig upp á nýtt: vefslóð vefsvæðisins þíns, útgáfur WordPress, PHP og Babilim, tungumál vefsvæðisins og tungumálin sem eru í notkun á því, auk opinbers lykils sem er útbúinn fyrir þetta vefsvæði.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'Sent við hverja athugun: listi yfir uppsettar viðbætur og þemu ásamt stöðu allra Babilim-þýðinga sem eru uppsettar fyrir þau, tungumálin í notkun og stuttir greiningarkóðar.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'Hver beiðni inniheldur vefslóð vefsvæðisins þíns og aðgangsteikn vefsvæðisins fylgir með þegar þjónustan þarfnast þess.','What Babilim sends to the service'=>'Hvað Babilim sendir til þjónustunnar','Your site\'s URL'=>'Vefslóð vefsvæðisins þíns','WordPress version'=>'Útgáfa WordPress','PHP version'=>'Útgáfa PHP','Babilim version'=>'Útgáfa Babilim','Your site\'s language'=>'Tungumál vefsvæðisins þíns','Languages in use on your site'=>'Tungumál í notkun á vefsvæðinu þínu','A public key for this site'=>'Opinber lykill fyrir þetta vefsvæði','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'Opinber lykill sem er útbúinn fyrir þetta vefsvæði og notaður til að sanna að beiðnir komi í raun frá þessu vefsvæði. Aðeins opinberi hlutinn er sendur; einkahlutinn verður eftir á vefsvæðinu þínu.','Installed plugins and themes'=>'Uppsettar viðbætur og þemu','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, and the languages it already includes. For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'Fyrir hverja uppsetta viðbót og hvert uppsett þema: nafn (slug), útgáfa, textalén, hvort það er skráð á WordPress.org og tungumálin sem það inniheldur nú þegar. Fyrir hverja Babilim-þýðingu sem þú hefur sett upp: hvaða útgáfa það er, hvenær hún var síðast athuguð og hvort hún stóðst skráarathugun.','Source files (only if you confirm an upload)'=>'Upprunaskrár (aðeins ef þú staðfestir innsendingu)','Diagnostic codes'=>'Greiningarkóðar','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'Allt að 20 stuttir greiningarkóðar (til dæmis þýðingarskrá sem stóðst ekki athugun), hver með viðbótinni eða þemanu, tungumálinu og tímanum þegar það gerðist. Þeir innihalda aldrei neinn texta af vefsvæðinu þínu né nokkurn þýddan texta.','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d vefur á þessu neti er stilltur á að eyða Babilim auðkenni sínu þegar viðbótinni er eytt. Þá væri ekki hægt að endurheimta greidda leyfið sem tengt er þeim vef sjálfkrafa; þú þyrftir að hafa samband við þjónustuver Babilim á %2$s. Til að halda auðkenninu skaltu ýta á Hætta við, taka hakið af „Eyða öllum Babilim gögnum við fjarlægingu“ í Babilim stillingum þess vefs og afvirkja aftur. Afvirkja samt?' . "\0" . '%1$d vefir á þessu neti eru stilltir á að eyða Babilim auðkenni sínu þegar viðbótinni er eytt. Þá væri ekki hægt að endurheimta greidda leyfið sem tengt er þeim vefjum sjálfkrafa; þú þyrftir að hafa samband við þjónustuver Babilim á %2$s. Til að halda auðkennunum skaltu ýta á Hætta við, taka hakið af „Eyða öllum Babilim gögnum við fjarlægingu“ í Babilim stillingum hvers vefs og afvirkja aftur. Afvirkja samt?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s ekkert að gera.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Veldu tungumálið.','%d failed'=>'%d mistókst' . "\0" . '%d mistókust','%d not yet tried'=>'%d ekki reynt enn' . "\0" . '%d ekki reynt enn','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d tilkynning bíður. „Always share“ og „Don\'t share“ gilda um þær allar.' . "\0" . '%d tilkynningar bíða. „Always share“ og „Don\'t share“ gilda um þær allar.','%d skipped'=>'%d sleppt' . "\0" . '%d sleppt','%d succeeded'=>'%d tókst' . "\0" . '%d tókust','%d to install'=>'%d til uppsetningar' . "\0" . '%d til uppsetningar','(a public key generated for this site)'=>'(opinber lykill sem var búinn til fyrir þennan vef)','(detected)'=>'(greint)','(generic codes and coordinates only)'=>'(aðeins almennir kóðar og hnit)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Hreinsun var sett í bið %1$s: %2$s. Engu var eytt.','A file in the component could not be read, so it was not packaged.'=>'Ekki tókst að lesa skrá í einingunni og hún var því ekki pökkuð.','A host that serves only one PHP request at a time cannot complete this step.'=>'Vefhýsing sem afgreiðir aðeins eina PHP-beiðni í einu getur ekki lokið þessu skrefi.','A part of the upload kept failing, so the upload was cancelled.'=>'Hluti upphleðslunnar mistókst ítrekað og hætt var við upphleðsluna.','A translation cannot be requested for that locale on this site right now.'=>'Ekki er hægt að biðja um þýðingu fyrir þessa staðfærslu á þessum vef eins og er.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Ritun í þýðingaskrána rakst á aðra beiðni á %1$s (%2$s) og var ekki beitt; nýjasta útgáfan var varðveitt.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Ekki tókst að ljúka ritun í þýðingaskrána á %1$s (%2$s) og henni var ekki beitt (%3$s).','Account'=>'Reikningur','Add another language'=>'Bæta við öðru tungumáli','Advanced'=>'Ítarlegt','All'=>'Allt','All free-plan slots for this site are used'=>'Öll pláss í ókeypis þjónustuleið fyrir þennan vef eru í notkun','All languages'=>'Öll tungumál','Already in WordPress core'=>'Þegar í kjarna WordPress','Already installed.'=>'Þegar uppsett.','Always share'=>'Always share','Another installation is running; try again in a moment.'=>'Önnur uppsetning er í gangi; reyndu aftur eftir augnablik.','Automatic installs'=>'Sjálfvirkar uppsetningar','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Sjálfvirkar uppsetningar eru nú óvirkar; kveiktu aftur á þeim í stillingunum ef þú vilt.','Available'=>'Tiltæk','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Hægt er að setja upp tiltækar þýðingar með einum smelli og biðja um þær sem vantar. Þegar kveikt er á sjálfvirkum uppsetningum eru þýðingar sem þjónustan skráir sem tiltækar fyrir tungumálin sem þú sérð um settar upp við samstillingu tvisvar á dag.','Available · %s'=>'Tiltæk · %s','Babilim'=>'Babilim','Babilim Settings'=>'Babilim stillingar','Babilim adds translations for every language checked here.'=>'Babilim bætir við þýðingum fyrir öll tungumál sem eru valin hér.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim gat ekki staðfest tímabundna möppu utan vefsins, þannig að íhlutnum var ekki pakkað og engu var hlaðið upp. Skilgreindu BABILIM_TEMP_DIR í wp-config.php sem skrifanlega möppu utan rótarmöppu vefsins (til dæmis möppu við hliðina á, en ekki inni í, opinberri möppu vefsvæðisins þíns), eða biddu vefhýsinguna þína um slíka.','Babilim could not finish checking this site.'=>'Babilim gat ekki lokið við að athuga þennan vef.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim gat ekki lokið virkjun (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim gat ekki lokið við að sannreyna þetta vefsvæði (þjónustan náði ekki sambandi við það aftur). Skráning er í bið.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim gat ekki staðfest þennan vef, því er engu hlaðið niður eða sett upp fyrr en staðfesting tekst.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim gat ekki staðfest þessa vefsíðu, því er engu hlaðið niður eða sett upp.','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim sækir þýðingar frá Babilim-þjónustunni fyrir viðbætur og þemu á þessu vefsvæði sem hafa engar þýðingar fyrir tungumálið þitt, og setur upp þær sem þjónustuleiðin þín nær yfir.','Babilim has not been enabled for this site yet.'=>'Babilim hefur ekki enn verið virkjað fyrir þennan vef.','Babilim has not installed any translation for this language.'=>'Babilim hefur ekki sett upp neina þýðingu fyrir þetta tungumál.','Babilim hit an error. Share an error report?'=>'Babilim rakst á villu. Deila villutilkynningu?','Babilim installed %d translation automatically since your last visit.'=>'Babilim setti upp %d þýðingu sjálfkrafa frá síðustu heimsókn þinni.' . "\0" . 'Babilim setti upp %d þýðingar sjálfkrafa frá síðustu heimsókn þinni.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim er óvirkt. Engu meira er sent; þýðingar sem þegar eru uppsettar halda áfram að virka.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim er virkt: þessi vefur er staðfestur og %d eining fannst.' . "\0" . 'Babilim er virkt: þessi vefur er staðfestur og %d einingar fundust.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim er að virkja og athuga þessa vefsíðu… (síðasta tilraun: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim er að virkja og athuga þessa vefsíðu… Endurhlaðið þessa síðu eða bíðið eftir að tímasetta athugunin klárist.','Babilim is not enabled.'=>'Babilim er ekki virkt.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim er stillt á að eyða auðkenni þessa vefs þegar viðbótinni er eytt. Þá væri ekki hægt að endurheimta greidda leyfið sem tengt er þessum vef sjálfkrafa; þú þyrftir að hafa samband við þjónustuver Babilim á %s. Til að halda auðkenninu skaltu ýta á Hætta við, taka hakið af „Eyða öllum Babilim gögnum við fjarlægingu“ í Babilim stillingum og afvirkja aftur. Afvirkja samt?','Babilim ran out of time for this step and will continue on the next check.'=>'Tíminn sem Babilim hafði til að ljúka þessu skrefi rann út og Babilim heldur áfram við næstu athugun.','Babilim settings'=>'Babilim stillingar','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Þjónustan seinkar samstillingu Babilim tímabundið (hraðatakmörkun); það reynir aftur eftir %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim var uppfært á meðan þessi upphleðsla beið. Gamla pakkanum var hent; staðfestu upphleðsluna aftur.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim mun hlaða upp þessum skrám úr %1$s (útgáfa %2$s): hverri .php og .js skrá, hverri block.json skrá og readme.txt, readme.md, style.css og theme.json í aðalmöppu þess. Þær eru notaðar til að finna textann sem þarf að þýða og til að bera kennsl á viðbótina eða þemað.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest er ekki tiltækt: %s','Back'=>'Til baka','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Keyptir þú leyfi fyrir þetta lén áður? Sláðu inn endurheimtarkóðann sem þú fékkst við greiðslu.','Broken placeholder'=>'Bilaður staðgengill','Build'=>'Útgáfa','Built'=>'Smíðað','Bulk actions apply only to the selected language of each selected component.'=>'Magnaðgerðir gilda aðeins um valið tungumál hverrar valinnar einingar.','Bulk actions apply to every matching language of each selected component.'=>'Magnaðgerðir gilda um öll samsvarandi tungumál hverrar valinnar einingar.','Bulk download:'=>'Hópniðurhal:','Bulk request:'=>'Hópbeiðni:','Bulk update:'=>'Hópuppfærsla:','Bundled with the plugin'=>'Fylgir með viðbótinni','Bundled with the theme'=>'Fylgir með þemanu','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Með því að smella á Virkja samþykkir þú að senda upplýsingarnar hér að ofan til Babilim.','By continuing you confirm that you have the right to upload this component.'=>'Með því að halda áfram staðfestir þú að þú hafir rétt til að senda þessa einingu inn.','Cancel'=>'Hætta við','Category'=>'Flokkur','Check again'=>'Athuga aftur','Check again now'=>'Athuga aftur núna','Checkout is not available for this site right now.'=>'Greiðsla er ekki tiltæk fyrir þennan vef núna.','Choose'=>'Velja','Choose a category…'=>'Veldu flokk…','Choose a language'=>'Veldu tungumál','Choose a language…'=>'Veldu tungumál…','Clear filters'=>'Hreinsa síur','Close'=>'Loka','Component'=>'Eining','Confirm'=>'Staðfesta','Conflicting keys'=>'Lyklar í árekstri','Continue'=>'Halda áfram','Continue next batch (%d left)'=>'Halda áfram með næstu lotu (%d eftir)','Continuing…'=>'Held áfram…','Could not back up %s before replacing it.'=>'Ekki tókst að taka afrit af %s áður en henni var skipt út.','Could not create the package archive.'=>'Ekki tókst að búa til pakkasafnið.','Could not determine active components; the existing merged index was left unchanged.'=>'Ekki tókst að ákvarða virkar einingar; núverandi sameinaða skráin var látin óbreytt.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Ekki tókst að ákvarða uppsettar viðbætur/þemu; hreinsun sleppt, engu var eytt.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Ekki tókst að hlaða fullum lista yfir WordPress.org staðfærslur frá þjónustunni, því er ekki hægt að bæta við öðru tungumáli núna.','Could not move %s into place.'=>'Ekki tókst að færa %s á sinn stað.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Ekki tókst að færa sameinuðu skrána fyrir \'%s\' á sinn stað; fyrri skráin sem var í notkun (ef einhver) var fjarlægð frekar en að skilja hana eftir hálfuppfærða. Engin viðbót fyrir sjálfgefið textalén er veitt fyrir þessa staðfærslu fyrr en næsta vel heppnaða endurbygging.','Could not open zip: %s'=>'Ekki tókst að opna zip: %s','Could not prepare %s for rollback.'=>'Ekki tókst að undirbúa %s fyrir afturköllun.','Could not read %s back after moving it into place.'=>'Ekki tókst að lesa %s aftur eftir að hún var færð á sinn stað.','Could not read: %s'=>'Ekki tókst að lesa: %s','Could not restore the purchase: %s'=>'Ekki tókst að endurheimta kaupin: %s','Could not show a new restore code: %s'=>'Ekki tókst að sýna nýjan endurheimtarkóða: %s','Could not stage %s'=>'Ekki tókst að undirbúa %s','Could not stage default/%s'=>'Ekki tókst að undirbúa default/%s','Could not start checkout: %s'=>'Ekki tókst að hefja greiðslu: %s','Could not verify entry count for %s'=>'Ekki tókst að staðfesta fjölda færslna fyrir %s','Could not write the downloaded package to disk.'=>'Ekki tókst að skrifa niðurhalaða pakkann á diskinn.','Could not write the staged merged index.'=>'Ekki tókst að skrifa undirbúnu sameinuðu skrána.','Current translation'=>'Núverandi þýðing','Custom overrides'=>'Sérsniðnar yfirskriftir','Danger zone'=>'Hættusvæði','Default supplement entry count mismatch.'=>'Fjöldi færslna í sjálfgefnu viðbótinni passar ekki.','Delete all Babilim data on uninstall'=>'Eyða öllum Babilim gögnum við fjarlægingu','Disable Babilim'=>'Gera Babilim óvirkt','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Gera Babilim óvirkt? Uppsettar þýðingar eru varðveittar en engar frekari athuganir eða niðurhal fara fram.','Don\'t share'=>'Don\'t share','Download'=>'Sækja','Downloaded and installed.'=>'Sótt og uppsett.','Downloading…'=>'Sæki…','Downloads: %1$d/%2$d (%3$s)'=>'Niðurhal: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Framlag hverrar einingar til viðbótar fyrir sjálfgefið textalén hverrar staðfærslu.','Enable Babilim'=>'Virkja Babilim','Enabling…'=>'Verið er að virkja…','English (United States)'=>'enska (Bandaríkin)','Entries'=>'Færslur','Entry count mismatch for %s'=>'Fjöldi færslna passar ekki fyrir %s','Error reports'=>'Villutilkynningar','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Sérhver staðfærsla í notkun á þessum vef (staðfærsla vefsins, uppsettir tungumálapakkar, staðfærslur notenda og þær sem þú bætir við handvirkt). Engin staðfærsla er meðhöndluð öðruvísi en önnur.','Excluded'=>'Undanskilið','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Skrár með önnur heiti eða endingar eru ekki teknar með, né heldur möppurnar uploads, cache, logs, backup, data, vendor, node_modules og languages, faldar skrár eða skrár með nöfn sem samsvara algengum mynstrum fyrir skrár með viðkvæmum upplýsingum (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Kóðaskrár geta samt innihaldið texta eða gögn sem þú vilt ekki deila; athugaðu þær ef þú ert í vafa. Þjónustan fjarlægir sömu tegundir skráa aftur við móttöku.','Fills in missing translations for the plugins and themes already installed on your site.'=>'Fyllir inn þýðingar sem vantar fyrir viðbæturnar og þemun sem þegar eru uppsett á vefnum þínum.','Free'=>'Ókeypis','Free-plan slots'=>'Pláss í ókeypis þjónustuleið','General'=>'Almennt','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ef kveikt er á þessu eyðir fjarlæging einnig auðkenni þessa vefs. Ekki er hægt að endurheimta greidda leyfið sem tengt er þessum vef sjálfkrafa eftir það; þú þyrftir að hafa samband við þjónustuver Babilim á %s til að fá það aftur.','Included'=>'Innifalið','Included in index'=>'Innifalið í skránni','Install available translations automatically'=>'Setja upp tiltækar þýðingar sjálfvirkt','Installed'=>'Uppsett','Installed translations are kept, but no further checks or downloads will run.'=>'Uppsettar þýðingar eru varðveittar en engar frekari athuganir eða niðurhal fara fram.','Installed · %s'=>'Uppsett · %s','Installed · built for %1$s, this site has %2$s'=>'Uppsett · smíðað fyrir %1$s, þessi vefur er með %2$s','Installed · built for %s'=>'Uppsett · smíðað fyrir %s','Installed · built for %s, new version failed'=>'Uppsett · smíðað fyrir %s, ný útgáfa mistókst','Installed · built for %s, new version scheduled'=>'Uppsett · smíðað fyrir %s, ný útgáfa á áætlun','Installed · built for %s, translating the new version…'=>'Uppsett · smíðað fyrir %s, nýja útgáfan er þýdd…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'Uppsett · smíðað fyrir %s; þessi viðbót eða þema fellur ekki lengur undir þjónustuleið vefsvæðisins','Installed · built for a different version'=>'Uppsett · smíðað fyrir aðra útgáfu','Installed · built for a different version, new version failed'=>'Uppsett · smíðað fyrir aðra útgáfu, ný útgáfa mistókst','Installed · built for a different version, new version scheduled'=>'Uppsett · smíðað fyrir aðra útgáfu, ný útgáfa er tímasett','Installed · built for a different version, translating the new version…'=>'Uppsett · smíðað fyrir aðra útgáfu, nýja útgáfan er í þýðingu…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'Uppsett · smíðað fyrir aðra útgáfu; þessi viðbót eða þema fellur ekki lengur undir þjónustuleið vefsvæðisins','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Hún er geymd hjá hýsingaraðila þjónustunnar og unnin af gervigreindarlíkönum til að búa til þýðinguna.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Halda eigin þýðingaryfirskriftum mínum þegar öllu er eytt eða þessi viðbót er fjarlægð.','Language'=>'Tungumál','Language:'=>'Tungumál:','Languages'=>'Tungumál','Languages found on this site: %s.'=>'Tungumál sem fundust á þessari vefsíðu: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Síðasta hreinsun %1$s: %2$d nýmerkt, %3$d skrám eytt, %4$d færslum fjarlægðum.','Maintenance'=>'Viðhald','Maintenance status is not available right now.'=>'Staða viðhalds er ekki tiltæk núna.','Manifest unavailable: %s'=>'Manifest ekki tiltækt: %s','Negation reversed'=>'Neitun snúið við','No'=>'Nei','No build is available to download for this locale.'=>'Engin útgáfa er tiltæk til niðurhals fyrir þessa staðfærslu.','No cleanup has run yet.'=>'Engin hreinsun hefur verið keyrð enn.','No components match these filters. %s'=>'Engar einingar passa við þessar síur. %s','No components synced yet.'=>'Engar einingar hafa verið samstilltar enn.','No installed translation matches.'=>'Engin uppsett þýðing passar.','No language is managed yet.'=>'Ekkert tungumál er í umsjón enn.','No pending challenge for this nonce.'=>'Engin bíðandi áskorun fyrir þetta nonce.','No pending challenge to verify.'=>'Engin bíðandi áskorun til að staðfesta.','No plugins or themes found.'=>'Engar viðbætur eða þemu fundust.','No previous build to roll back to.'=>'Engin fyrri útgáfa til að snúa aftur til.','No record for %s'=>'Engin færsla fyrir %s','No site id is on file to rotate a token for.'=>'Ekkert vefauðkenni er skráð sem hægt er að endurnýja aðgangstákn fyrir.','No — component inactive'=>'Nei — eining óvirk','No — component removed'=>'Nei — eining fjarlægð','No — installed version differs from the active one'=>'Nei — uppsetta útgáfan er önnur en sú virka','Not a valid server_build_id: %s'=>'Ekki gilt server_build_id: %s','Not covered by the free service plan'=>'Ekki innifalið í ókeypis þjónustuleið','Not installed'=>'Ekki uppsett','Not registered yet'=>'Ekki skráð enn','Not supported'=>'Ekki studd','Not verified'=>'Ekki staðfest','Note (optional)'=>'Athugasemd (valfrjálst)','Nothing to choose.'=>'Ekkert til að velja.','Nothing to confirm.'=>'Ekkert til að staðfesta.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Slökkt sjálfgefið: ef viðbótinni er eytt er auðkenni þessa vefsvæðis varðveitt svo hægt sé að endurnýta það við enduruppsetningu.','One or more served files no longer match the manifest.'=>'Ein eða fleiri afgreiddar skrár passa ekki lengur við manifest.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Einskiptiskaup fyrir þessa vefsíðu: %1$s %2$s. Inniheldur allar framtíðaruppfærslur á þýðingum. Greiðslan fer fram í gegnum Paddle í nýjum flipa.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Aðeins netstjóri getur gert þetta, því það breytir þýðingarskrám sem öll vefsvæði á þessu neti deila.','Only plugins and themes can be packaged.'=>'Aðeins viðbætur og þemu er hægt að pakka.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Aðeins þegar þú staðfestir upphleðslu fyrir viðbót eða þema sem er ekki á WordPress.org: hver .php og .js skrá, hver block.json skrá og readme.txt, readme.md, style.css og theme.json í aðalmöppu þess íhlutar, sem zip, eftir að skrám sem passa við algeng leyndarmál hefur verið sleppt.','Open Babilim settings'=>'Opna Babilim stillingar','Original language'=>'Upprunalegt tungumál','Original string'=>'Upprunalegur strengur','Paid'=>'Greitt','Partner'=>'Samstarfsaðili','Please check that your site can be reached from the internet, then try again.'=>'Athugaðu hvort hægt sé að ná í vefsíðuna þína af internetinu og reyndu svo aftur.','Please choose a category for this report.'=>'Veldu flokk fyrir þessa tilkynningu.','Plugin'=>'Viðbót','Plugin · %s'=>'Viðbót · %s','Plugins'=>'Viðbætur','Preview'=>'Forskoðun','Purchase restored. This site is now licensed.'=>'Kaupin voru endurheimt. Þessi vefsíða er nú með leyfi.','Re-parsed entry count did not match the built index.'=>'Fjöldi færslna eftir endurtúlkun passaði ekki við byggðu skrána.','Re-verify'=>'Staðfesta aftur','Rebuild index now'=>'Endurbyggja atriðaskrána núna','Refusing to write outside the Babilim language-file directory.'=>'Neita að skrifa utan tungumálaskrámöppu Babilim.','Registration response was missing required fields.'=>'Í skráningarsvarinu vantaði nauðsynlega reiti.','Registration restarted.'=>'Skráning hófst að nýju.','Remove'=>'Fjarlægja','Remove everything Babilim installed'=>'Fjarlægja allt sem Babilim setti upp','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Fjarlægja allt sem Babilim setti upp? Þetta eyðir öllum tungumálaskrám sem Babilim setti upp fyrir allar viðbætur og þemu á þessum vef.','Remove the %2$s translation of %1$s from this site?'=>'Fjarlægja þýðinguna %2$s fyrir %1$s af þessum vef?','Removed %d installed component.'=>'%d uppsett eining fjarlægð.' . "\0" . '%d uppsettar einingar fjarlægðar.','Removed after a failed integrity check'=>'Fjarlægt eftir misheppnaða heildarleikaprófun','Removed.'=>'Fjarlægt.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Fjarlægir allar tungumálaskrár sem Babilim hefur sett upp fyrir allar viðbætur og þemu á þessum vef.','Report a problem'=>'Tilkynna vandamál','Report translation'=>'Tilkynna þýðingu','Request newer translation'=>'Biðja um nýrri þýðingu','Request translation'=>'Biðja um þýðingu','Requestable'=>'Hægt að biðja um','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Þegar þú biður um þýðingu fær þessi viðbót eða þetta þema eitt af plássum ókeypis þjónustuleiðarinnar fyrir þennan vef (hámarkið er %1$d fyrir þemu og %2$d fyrir viðbætur), nema það hafi nú þegar pláss. Plássið helst í notkun og misheppnuð þýðing losar það ekki.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Þegar þú biður um þýðingu fær þessi viðbót eða þetta þema eitt af plássum ókeypis þjónustuleiðarinnar fyrir þennan vef, nema það hafi nú þegar pláss. Plássið helst í notkun og misheppnuð þýðing losar það ekki.','Requesting…'=>'Bið um…','Restart registration'=>'Hefja skráningu aftur','Restore code'=>'Endurheimtarkóði','Restore purchase'=>'Endurheimta kaup','Retry request'=>'Reyna beiðni aftur','Roll back'=>'Afturkalla','Roll back and report'=>'Afturkalla og tilkynna','Roll back and send report'=>'Afturkalla og senda tilkynningu','Roll back the %2$s translation of %1$s to the previous build?'=>'Færa %2$s þýðinguna á %1$s til baka í fyrri smíð?','Rolled back and reported.'=>'Sneri til baka og tilkynnti.','Rolled back to the previous build.'=>'Sneri aftur í fyrri útgáfu.','Rolled back, but the report could not be sent: %s'=>'Sneri til baka, en ekki tókst að senda tilkynninguna: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Afturköllun myndi skrifa yfir \'%1$s\' (%2$s), sem er nú afgreidd fyrir aðra uppsetta einingu (%3$s); engu var breytt.','Rotate-token response was missing site_token.'=>'Í svarinu við skiptingu tákns vantaði site_token.','Save changes'=>'Vista breytingar','Scheduled, waiting to be processed'=>'Áætlað, bíður vinnslu','Search'=>'Leita','Search components'=>'Leita í einingum','Search the installed translations'=>'Leita í uppsettum þýðingum','Select all'=>'Velja allt','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Veldu færri einingar: að hámarki %1$d aðgerðir í hverri keyrslu (þú valdir %2$d).','Send report'=>'Senda skýrslu','Service plan'=>'Þjónustuleið','Settings'=>'Stillingar','Share error reports'=>'Deila villutilkynningum','Share this report'=>'Deila þessari tilkynningu','Show a new restore code'=>'Sýna nýjan endurheimtarkóða','Show the "Report translation" entry in the admin toolbar'=>'Sýna „Tilkynna þýðingu“ á stjórnborðsverkfærastikunni','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Sumur texti þessarar einingar er harðkóðaður af höfundi hennar og tungumálapakki getur ekki þýtt hann.','Status'=>'Staða','Status unknown'=>'Staða óþekkt','String context'=>'Samhengi strengs','Suggested translation'=>'Tillaga að þýðingu','Supplementary translation index'=>'Skrá yfir viðbótarþýðingar','Supplementary translation index rebuilt.'=>'Viðbótarþýðingaskrá endurbyggð.','Supplementary translation maintenance'=>'Viðhald viðbótarþýðinga','Supplementary translations'=>'Viðbótarþýðingar','Sweep aborted without orphaning anything: %s.'=>'Hreinsun hætt án þess að nokkuð yrði munaðarlaust: %s.','Sweep complete: %d file deleted.'=>'Hreinsun lokið: %d skrá eytt.' . "\0" . 'Hreinsun lokið: %d skrám eytt.','Sweep now'=>'Skanna núna','Sync complete.'=>'Samstillingu lokið.','Thank you. Your report was sent.'=>'Takk fyrir. Tilkynningin þín var send.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Þessi eining er ekki uppsett á þessum vef, því er ekki hægt að biðja um þýðingu fyrir hana.','That does not look like a restore code.'=>'Þetta lítur ekki út eins og endurheimtarkóði.','That is not a valid WordPress locale code. Nothing was saved.'=>'Þetta er ekki gildur WordPress staðfærslukóði. Engu var vistað.','That is not a valid build identifier.'=>'Þetta er ekki gilt smíðakenni.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Sá upphleðsluskjár var úreltur: önnur upphleðsla hefur verið undirbúin síðan. Engu var sent. Skoðaðu þá núverandi í Þýðingalistanum.','The change could not be recorded in the translation index; please try again.'=>'Ekki tókst að skrá breytinguna í þýðingaskrána; reyndu aftur.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Hreinsunin keyrði, en ekki var hægt að skrá allar breytingar hennar í þýðingaskrána; næsta hreinsun reynir aftur.','The component has no files that can be uploaded.'=>'Íhluturinn hefur engar skrár sem hægt er að hlaða upp.','The component is not inside the plugins or themes directory.'=>'Einingin er ekki í viðbóta- eða þemamöppunni.','The component\'s main file was not found.'=>'Aðalskrá einingarinnar fannst ekki.','The download response was missing a usable location.'=>'Í niðurhalssvarinu vantaði nothæfa staðsetningu.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Færslan opnar glugga þar sem hægt er að leita í þýðingunum sem Babilim setti upp á þessum vef og tilkynna eina þeirra.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Reiturinn „%1$s“ er of langur: hann hefur %2$d stafi og hámarkið er %3$d. Engu var sent; styttu hann og reyndu aftur.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Ókeypis þjónustuleiðin gefur hverjum vef takmarkaðan fjölda plássa fyrir viðbætur og þemu; plássin sem eru í notkun birtast í stillingunum eftir að þú virkjar Babilim.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Uppgefið lén \'%1$s\' samsvarar hvorki slug \'%2$s\' í manifest pakkans né text_domain \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Sameinaða skráin fyrir \'%s\' var endurbyggð, en þýðingaskráin gat ekki skráð hana; næsta endurbygging reynir aftur.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Upprunalegi textinn og þýðingarnar sem gerðar eru úr honum verða veittar öðrum vefjum sem setja upp sömu útgáfu.','The package declares no main translation file.'=>'Pakkinn tilgreinir enga aðalþýðingarskrá.','The package has no %s for its own text domain.'=>'Pakkinn hefur ekkert %s fyrir eigið textalén.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Tegund \'%1$s\' í manifest pakkans samsvarar ekki umbeðinni tegund \'%2$s\'.','The package produced no servable main translation file.'=>'Pakkinn bjó ekki til neina nothæfa aðalþýðingarskrá.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Textalén pakkans \'%1$s\' samsvarar ekki eintaki þessa vefs af einingunni (\'%2$s\', þannig að hann var ekki settur upp.','The packaged component could not be read.'=>'Ekki tókst að lesa pakkaða eininguna.','The registration challenge is not in the expected form.'=>'Skráningaráskorunin er ekki á væntanlegu sniði.','The report could not be sent.'=>'Ekki tókst að senda tilkynninguna.','The search could not be completed.'=>'Ekki tókst að ljúka leitinni.','The service asked this site to wait before syncing again.'=>'Þjónustan bað þennan vef um að bíða áður en hann samstillir aftur.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Þjónustan náði ekki sambandi við vefinn þinn. Líklega er eldveggur, öryggisviðbót eða regla hjá vefhýsingu að loka á beiðnina; leyfðu beiðnir til /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Upphleðslutilboð þjónustunnar var ófullnægjandi.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Textalénið \'%1$s\' (%2$s) er þegar í notkun fyrir aðra uppsetta einingu (%3$s); ekkert var sett upp.','The upload is kept until you ask Babilim to delete it.'=>'Innsendingin er geymd þar til þú biður Babilim um að eyða henni.','Theme'=>'Þema','Theme · %s'=>'Þema · %s','Themes'=>'Þemu','There is no upload in progress.'=>'Engin innsending er í gangi.','There is no upload waiting for confirmation.'=>'Engin innsending bíður staðfestingar.','These are the languages this site uses. You can change them in %s.'=>'Þetta eru tungumálin sem þessi vefur notar. Þú getur breytt þeim í %s.','These fields will be sent:'=>'Þessir reitir verða sendir:','This build is not one this site currently knows about for this component/locale.'=>'Þessi útgáfa er ekki ein af þeim sem þessi vefur þekkir núna fyrir þessa einingu og staðfærslu.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Þessi eining tilgreinir ekki útgáfunúmer, því er ekki hægt að biðja um þýðingu fyrir hana.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Þessi eining er stærri en þjónustan tekur við og því er ekki hægt að hlaða henni upp.','This component was already uploaded. Babilim is checking it now.'=>'Þessari einingu var þegar hlaðið upp. Babilim er að athuga hana núna.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Útgáfunúmer þessarar einingar er lengra en %d stafir, sem Babilim ræður ekki við, því er ekki hægt að biðja um þýðingu fyrir hana.','This issues a new restore code and the previous one stops working. Continue?'=>'Þetta gefur út nýjan endurheimtarkóða og sá fyrri hættir að virka. Halda áfram?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Þetta net hefur of marga vefi til að hægt sé að athuga þá einn og einn og sumir þeirra gætu verið stilltir á að eyða Babilim auðkenni sínu þegar viðbótinni er eytt. Þá væri ekki hægt að endurheimta greidda leyfið sem tengt er slíkum vef sjálfkrafa; þú þyrftir að hafa samband við þjónustuver Babilim á %s. Til að halda auðkennunum skaltu ýta á Hætta við, taka hakið af „Eyða öllum Babilim gögnum við fjarlægingu“ í Babilim stillingum hvers vefs og afvirkja aftur. Afvirkja samt?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Útgáfa þessarar viðbótar sjálfrar, svo þjónustan geti beðið þig um að uppfæra hana ef hún er of gömul til að eiga samskipti við hana.','This report does not name a valid plugin or theme and locale.'=>'Þessi skýrsla nefnir hvorki gilda viðbót eða þema né staðfærslu.','This report does not name an installed string.'=>'Þessi skýrsla tilgreinir ekki Nafn uppsetts textastrengs.','This report is missing a valid build to report against.'=>'Þessa tilkynningu vantar gilda útgáfu til að tilkynna um.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Þessi tilkynning verður birt opinberlega á GitHub og þriðju aðilar kunna að geyma hana.','This restore code was not recognised for this site.'=>'Þessi endurheimtarkóði þekktist ekki fyrir þennan vef.','This site already has an active registration that can no longer be recovered automatically.'=>'Þetta vefsvæði er þegar með virka skráningu sem ekki er lengur hægt að endurheimta sjálfkrafa.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Þessi vefur er með %1$d einingar á %2$d tungumálum, sem krefst %3$d athugunarlota; Babilim getur séð um í mesta lagi %4$d í hverri keyrslu. Fækkaðu stýrðum tungumálum í stillingum eða gerðu ónotuð viðbætur og þemu óvirk, og ýttu síðan á Athuga aftur núna.','This site has no purchase to show a code for.'=>'Engin kaup eru tengd þessum vef sem hægt er að sýna kóða fyrir.','This site is already licensed. Reload the page.'=>'Þetta vefsvæði er þegar með leyfi. Endurhlaðið síðuna.','This site is not registered with Babilim yet.'=>'Þetta vefsvæði hefur ekki enn verið skráð hjá Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Þessi vefsíða er stærri en þjónustan tekur við í einni samstillingu, því var sumu sleppt: %1$d einingum og %2$d tungumálum.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Þetta vefsvæði er hluti af fjölsetursneti sem setur ekki upp nýjar þýðingar sjálfkrafa. Þýðingar sem þegar eru uppsettar eru áfram uppfærðar.','This site is verified.'=>'Þessi vefur er staðfestur.','This site must be verified first.'=>'Fyrst þarf að staðfesta þennan vef.','This site\'s URL, so the service can verify you own it.'=>'Vefslóð þessa vefs, svo þjónustan geti staðfest að þú eigir hann.','This site\'s address is too long for Babilim to register.'=>'Vistfang þessa vefs er of langt til að Babilim geti skráð það.','This site\'s configured locale.'=>'Stillt staðfærsla þessa vefs.','This site\'s locale code is not one Babilim can register.'=>'Staðfærslukóði þessa vefs er ekki einn sem Babilim getur skráð.','This string can\'t be reported from this site.'=>'Ekki er hægt að tilkynna þessa textastreng frá þessu vefsvæði.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Þessi textastrengur er ekki meðal þýðinga sem eru uppsettar á þessu vefsvæði. Leitaðu aftur og veldu hann af listanum.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Þessi þýðing var uppfærð eftir að þú leitaðir. Leitaðu aftur og veldu textastrenginn af nýja listanum.','To translate this component, Babilim needs its source.'=>'Til að þýða þessa einingu þarf Babilim frumkóða hennar.','Too many attempts. Try again tomorrow.'=>'Of margar tilraunir. Reyndu aftur á morgun.','Too many reports today. Try again tomorrow.'=>'Of margar tilkynningar í dag. Reyndu aftur á morgun.','Too many requests.'=>'Of margar beiðnir.','Toolbar'=>'Verkfærastika','Translating…'=>'Þýði…','Translation does not load'=>'Þýðing hleðst ekki','Translation failed'=>'Þýðing mistókst','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Þýðingarskrár sem þú setur í %s hafa alltaf forgang yfir skrár frá Babilim. Þær eru varðveittar nema þú afhakir þetta.','Translation requested.'=>'Beðið um þýðingu.','Translations'=>'Þýðingar','Type'=>'Gerð','Type at least 2 characters to search.'=>'Sláðu inn að minnsta kosti 2 stafi til að leita.','Unexpected HTTP %d response.'=>'Óvænt HTTP-svar %d.','Uninstall'=>'Fjarlæging','Unknown kind: %s'=>'Óþekkt tegund: %s','Unsafe domain: %s'=>'Óöruggt lén: %s','Unsafe locale: %s'=>'Óörugg staðfærsla: %s','Unsafe slug: %s'=>'Óöruggt slug: %s','Unsafe text_domain: %s'=>'Óöruggt text_domain: %s','Update'=>'Uppfæra','Update available'=>'Uppfærsla í boði','Updates'=>'Uppfærslur','Updating…'=>'Uppfæri…','Upgrade this site'=>'Uppfæra þennan vef','Upload and request'=>'Senda inn og óska eftir þýðingu','Upload cancelled.'=>'Hætt við upphleðslu.','Upload complete — translation requested.'=>'Upphleðslu lokið — beðið um þýðingu.','Upload expired before it finished'=>'Innsendingin rann út áður en henni lauk','Upload in progress — continue or cancel'=>'Innsending í gangi — haltu áfram eða hættu við','Upload this component?'=>'Senda þessa einingu inn?','Upload was not accepted'=>'Innsendingin var ekki samþykkt','Uploading'=>'Sendi inn','Uploading part %1$d of %2$d…'=>'Sendi hluta %1$d af %2$d…','Uploading…'=>'Sendi inn…','Verified'=>'Staðfest','Verify response was missing site_token.'=>'Í staðfestingarsvarinu vantaði site_token.','Version %s'=>'Útgáfa %s','What is sent when you enable Babilim'=>'Hvað er sent þegar þú virkjar Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Þegar eitthvað bilar í Babilim skaltu senda villutilkynningu til Babilim-þjónustunnar svo hægt sé að birta hana sem opinbert vandamál á GitHub. Tilkynningin er send sem komandi frá þessu vefsvæði, með sömu auðkenningu og allar aðrar beiðnir til Babilim-þjónustunnar. Þjónustan birtir aðeins villukóðann og útgáfur sem opinbert vandamál á GitHub; opinbera vandamálið inniheldur hvorki vistfang vefsvæðis, efni né skráarslóðir. Slökkt sjálfgefið.','Where you saw this (optional)'=>'Hvar þú sást þetta (valfrjálst)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Á meðan kveikt er á þessu eru þýðingar sem þjónustan skráir sem tiltækar fyrir tungumálin sem þú sérð um settar upp við samstillingu tvisvar á dag.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Rangt í þessu samhengi','Wrong meaning'=>'Röng merking','Wrong plural form'=>'Rangt fleirtölusnið','Wrong term'=>'Rangt hugtak','Yes'=>'Já','You are not allowed to do this.'=>'Þú hefur ekki heimild til að gera þetta.','Your PHP version, for compatibility.'=>'PHP-útgáfa þín, vegna samhæfni.','Your WordPress version, to serve compatible translation files.'=>'WordPress-útgáfa þín, til að afhenda samhæfðar þýðingarskrár.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Nýi endurheimtarkóðinn þinn: %s. Geymdu hann á öruggum stað — fyrri kóðinn virkar ekki lengur.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Tilkynningin þín er unnin sjálfvirkt af AI-líkönum og getur bætt þessa þýðingu fyrir önnur vefsvæði.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Vefurinn þinn svaraði, en ekki með því sem búist var við. Önnur viðbót gæti verið að endurskrifa REST API, eða endapunkturinn gæti verið í skyndiminni; undanskildu /wp-json/babilim/v1/challenge frá skyndiminni og endurskrifun.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Vefsíðan þín var of lengi að svara. Reyndu aftur síðar og athugaðu hvort vefhýsingin sé of hæg eða yfirhlaðin.','Zip has no manifest.json.'=>'Zip-skráin hefur enga manifest.json.','Zip is missing expected default file: %s'=>'Zip-skrána vantar væntanlega sjálfgefna skrá: %s','Zip is missing expected file: %s'=>'Zip-skrána vantar væntanlega skrá: %s','_manifest.json has an unexpected structure'=>'_manifest.json hefur óvænta uppbyggingu','could not read _manifest.json: %s'=>'gat ekki lesið _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest vantar eða er með ógilt \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' í expected_manifest er ekki gilt build-auðkenni.','failed to parse _manifest.json: %s'=>'Tókst ekki að þátta _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'það myndi gera %1$d af %2$d stýrðum einingum munaðarlausar (meira en helming)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'það myndi gera sérhverja stýrða einingu af gerðinni %1$s munaðarlausa (%2$d af %2$d)','l10n.php entry count mismatch for %s'=>'Fjöldi færslna í l10n.php stemmir ekki fyrir %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json er með ógilt \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json er með ógilt \'default_domain_files\'.','manifest.json in the zip is not valid JSON.'=>'manifest.json í zip-skránni er ekki gilt JSON.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json vantar eða hefur ógilt \'%s\'.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json vantar eða er með ógilt \'build_no\'.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json vantar eða hefur ógilt \'entries\'.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json vantar eða er með ógilt \'extra_domains\'.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json vantar eða er með ógilt \'files\'.','manifest.json\'s \'%s\' does not match the expected value.'=>'\'%s\' í manifest.json samsvarar ekki væntanlegu gildi.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' í manifest.json er ekki gild útgáfustrengur.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' í manifest.json verður að vera \'plugin\' eða \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' í manifest.json er ekki gilt build-auðkenni.','manifest.json\'s \'status\' must be \'published\'.'=>'Reiturinn „status“ í manifest.json verður að hafa gildið „published“.','nonce must be a hexadecimal string.'=>'nonce verður að vera sextándakerfisstrengur.','per day'=>'á dag','rc_…'=>'rc_…','sha256 mismatch for %s'=>'sha256 stemmir ekki fyrir %s','sha256 mismatch for default/%s'=>'sha256 stemmir ekki fyrir default/%s','component kind in the sweep brake messageplugin'=>'viðbót','component kind in the sweep brake messagetheme'=>'þema','problem report categoryOther'=>'Annað','translation statusAvailable'=>'Tiltæk','translation statusInstalled'=>'Uppsett']];